/**
 * QR images are generated by the current GreanLean origin. Passing only the
 * canonical path avoids coupling the image request to language/showcase query
 * parameters or to the www/apex hostname used to render the page.
 */
export function canonicalQrRequestTarget(rawTarget: string) {
  const value = String(rawTarget || "").trim();
  try {
    const target = new URL(value, "https://qr-target.invalid");
    return target.pathname;
  } catch {
    return value.split(/[?#]/, 1)[0];
  }
}
